const b = $input.first().json.body || $input.first().json || {};
const op = (b.op || '').toString();
const q = (s) => (s || '').toString().replace(/'/g, "''");
const qi = (v) => { const n = parseInt(v); if (isNaN(n)) throw new Error('bad id'); return n; };
let sql = '', sql2 = '';
if (op === 'list') {
  sql = `SELECT u.id, u.username, u.display_name, u.is_active, u.created_at, COALESCE(string_agg(g.name, ',' ORDER BY g.name), '') AS groups FROM cd_users u LEFT JOIN cd_user_groups ug ON ug.user_id = u.id LEFT JOIN cd_groups g ON g.id = ug.group_id GROUP BY u.id ORDER BY u.id`;
} else if (op === 'list-groups') {
  sql = `SELECT id, name, description FROM cd_groups ORDER BY id`;
} else if (op === 'create') {
  const un = (b.username || '').toString().trim();
  if (!/^[A-Za-z0-9_.@-]{3,64}$/.test(un)) throw new Error('ชื่อผู้ใช้ไม่ถูกต้อง');
  const ph = (b.pass_hash || '').toString();
  if (ph.length < 20 || ph[0] !== '$') throw new Error('pass_hash ไม่ถูกต้อง');
  const dn = q((b.display_name || '').slice(0, 150));
  const gids = Array.isArray(b.groups) ? b.groups.map(g => parseInt(g)).filter(g => g > 0) : [];
  sql = `INSERT INTO cd_users (username, pass_hash, display_name) VALUES ('${q(un)}', '${q(ph)}', '${dn}') RETURNING id`;
  sql2 = gids.length ? '__GRANTS__:' + gids.join(',') + ':' + q(un) : '';
} else if (op === 'setpass') {
  const id = qi(b.id);
  const ph = (b.pass_hash || '').toString();
  if (ph.length < 20 || ph[0] !== '$') throw new Error('pass_hash ไม่ถูกต้อง');
  sql = `UPDATE cd_users SET pass_hash = '${q(ph)}' WHERE id = ${id}`;
} else if (op === 'active') {
  const id = qi(b.id);
  sql = `UPDATE cd_users SET is_active = ${parseInt(b.is_active) === 1 ? 1 : 0} WHERE id = ${id}`;
} else if (op === 'display') {
  const id = qi(b.id);
  sql = `UPDATE cd_users SET display_name = '${q((b.display_name || '').slice(0, 150))}' WHERE id = ${id}`;
} else if (op === 'groups') {
  const id = qi(b.id);
  const gids = Array.isArray(b.groups) ? b.groups.map(g => parseInt(g)).filter(g => g > 0) : [];
  sql = `DELETE FROM cd_user_groups WHERE user_id = ${id}`;
  sql2 = gids.length ? '__GRANTSID__:' + gids.join(',') + ':' + id : '';
} else if (op === 'delete') {
  const id = qi(b.id);
  sql = `DELETE FROM cd_users WHERE id = ${id}`;
} else if (op === 'group_add') {
  const nm = (b.name || '').toString().trim().toUpperCase();
  if (!/^[A-Z0-9_]{2,32}$/.test(nm)) throw new Error('ชื่อกลุ่มไม่ถูกต้อง');
  sql = `INSERT INTO cd_groups (name, description) VALUES ('${nm}', '${q((b.description || '').slice(0, 255))}')`;
} else if (op === 'group_del') {
  const id = qi(b.id);
  sql = `DELETE FROM cd_groups WHERE id = ${id} AND name NOT IN ('ADMIN','STAFF')`;
} else { throw new Error('unknown op'); }
return [{ json: { sql: sql, sql2: sql2, op: op } }];

const prev = $input.first().json;
const b = $('Build SQL').first().json;
let parts = (b.sql2 || '').split(':');
const kind = parts[0] || '';
const gids = (parts[1] || '').split(',').map(g => parseInt(g)).filter(g => g > 0);
const who = parts.slice(2).join(':');
let sql = '';
if (kind === '__GRANTS__') {
  sql = gids.map(g => `INSERT INTO cd_user_groups (user_id, group_id) SELECT id, ${g} FROM cd_users WHERE username = '${who.replace(/'/g, "''")}' ON CONFLICT DO NOTHING;`).join('');
} else if (kind === '__GRANTSID__') {
  sql = gids.map(g => `INSERT INTO cd_user_groups (user_id, group_id) VALUES (${parseInt(who)}, ${g}) ON CONFLICT DO NOTHING;`).join('');
} else { sql = 'SELECT 1'; }
return [{ json: { sql: sql } }];

const op = $('Build SQL').first().json.op || '';
const rows = $('Run SQL').all().map(r => r.json);
if (op === 'list') {
  const users = rows.map(u => ({ ...u, groups: (u.groups || '').split(',').filter(Boolean) }));
  return [{ json: { ok: true, users: users } }];
}
if (op === 'list-groups') {
  return [{ json: { ok: true, groups: rows } }];
}
if (op === 'create') {
  const r = rows.find(r => r.id !== undefined) || {};
  return [{ json: { ok: true, id: r.id || 0 } }];
}
return [{ json: { ok: true } }];
